enum DeclReferenceError: DiagnosticMessage {
  case nonLiteral

  var message: String {
    switch self {
    case .nonLiteral:
      return "only literals are permitted"
    }
  }

  var diagnosticID: MessageID {
    init(domain: "SwiftMacros", id: "\(self)")
  }

  var severity: DiagnosticSeverity {
    .error
  }
}

